draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 20, 0, 2 * Math.PI * (1 + t / 10));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2);
  ctx.lineTo(W / 2 + 30 * Math.sin(t), H / 2 + 30 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 30 * Math.sin(t), H / 2 + 30 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
